import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {ToastComponent} from "./toast.component";
import {PI_TOAST_ACTION, PI_TOAST_CARD} from "./toast.types";

export * from "./toast.types";

registerCardComponent({
  name: PI_TOAST_CARD,
  component: ToastComponent,
  events: actionTypesToEvents(PI_TOAST_ACTION),
});

import React, {useEffect, useRef, useState} from "react";
import {
  Card,
  type PiCardProps,
  type PiCardRef,
  usePiReducer,
  type ReduxAction,
  type ReduxState,
} from "@pihanga2/core";
import {toast} from "sonner";

import {
  type ShowToastEvent,
  TOAST_OP_ACTION,
  type ToastPosition,
  type ToastType,
  type PiToastEvents,
  type PiToastProps,
} from "./toast.types";

export const ToastComponent = (
  props: PiCardProps<PiToastProps, PiToastEvents>,
): React.ReactNode => {
  const {
    variant: defaultVariant = "default",
    duration: defaultDuration = 4000,
    dismissible: defaultDismissible = true,
    className: defaultClassName,
    onClosed,
    cardName,
  } = props;

  // State for tracking Redux-triggered toast messages
  const [currentToast, setCurrentToast] = useState<{
    message?: string;
    description?: string;
    contentCard?: PiCardRef;
    variant: ToastType;
    position?: ToastPosition;
    duration: number;
  } | null>(null);

  // Listen for showToast Redux messages
  // This allows triggering toasts from anywhere via dispatchShowToast
  usePiReducer<ReduxState, ShowToastEvent & ReduxAction>(
    TOAST_OP_ACTION.SHOW,
    (_, action) => {
      // Only respond if message is for this card or no specific cardName is set
      if (action.cardName && action.cardName !== cardName) {
        return;
      }
      setCurrentToast({
        message: action.message,
        description: action.description,
        contentCard: action.contentCard,
        variant: action.variant ?? defaultVariant,
        position: action.position,
        duration: action.duration ?? defaultDuration,
      });
    },
    cardName,
  );

  // Setup hooks before conditional rendering
  const toastIdRef = useRef<string | number | undefined>(undefined);

  useEffect(() => {
    // Only show toast if Redux message was received
    if (!currentToast) {
      return;
    }

    // Map our toast types to Sonner's toast function
    const toastFn =
      {
        success: toast.success,
        error: toast.error,
        info: toast.info,
        warning: toast.warning,
        default: toast,
      }[currentToast.variant] || toast;

    // Build className: combine default + variant-based class
    const className = [defaultClassName, `toast-${currentToast.variant}`]
      .filter(Boolean)
      .join(" ");

    // If contentCard is provided, render it as custom JSX content
    if (currentToast.contentCard) {
      const contentCard = currentToast.contentCard;
      const CustomToastContent = () => (
        <Card cardName={contentCard} parentCard={cardName} />
      );

      // Show the toast with custom card content
      toastIdRef.current = toastFn(CustomToastContent, {
        duration: currentToast.duration,
        position: currentToast.position || "bottom-right",
        dismissible: defaultDismissible,
        className,
        onDismiss: () => {
          setCurrentToast(null);
          onClosed({});
        },
        onAutoClose: () => {
          setCurrentToast(null);
          onClosed({});
        },
      });
    } else {
      // Show the toast with message and optional description
      toastIdRef.current = toastFn(currentToast.message, {
        description: currentToast.description,
        duration: currentToast.duration,
        position: currentToast.position || "bottom-right",
        dismissible: defaultDismissible,
        className,
        onDismiss: () => {
          setCurrentToast(null);
          onClosed({});
        },
        onAutoClose: () => {
          setCurrentToast(null);
          onClosed({});
        },
      });
    }

    // Cleanup on unmount
    return () => {
      if (toastIdRef.current !== undefined) {
        toast.dismiss(toastIdRef.current);
      }
    };
  }, [currentToast, defaultDismissible, defaultClassName, onClosed, cardName]);

  // This component doesn't render visible DOM itself
  // Sonner renders toasts in a portal via its Toaster component
  return <div data-pihanga={cardName} style={{display: "none"}} />;
};

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
  type DispatchF,
} from "@pihanga2/core";

export const PI_TOAST_CARD = "pi/toast";

export const Toast = createCardDeclaration<PiToastProps, PiToastEvents>(
  PI_TOAST_CARD,
);

export const TOAST_OP_ACTION = registerActions("toast/op", ["show"]);

/**
 * Dispatch helper to show a toast
 *
 * @param d - Dispatch function from Pihanga
 * @param ev - Toast event data
 *
 * @example
 * ```typescript
 * import {dispatchShowToast} from "@/cards/toast";
 *
 * dispatchShowToast(_dispatch, {
 *   message: "Success!",
 *   description: "Your changes were saved.",
 *   variant: "success",
 *   duration: 3000,
 * });
 * ```
 */
export const dispatchShowToast = (d: DispatchF, ev: ShowToastEvent) => {
  d({...ev, type: TOAST_OP_ACTION.SHOW});
};

/**
 * Action handler for when a toast is shown
 *
 * Use this in your reducers or effects to handle toast display events:
 *
 * @example
 * ```typescript
 * import {onShowToast} from "@/cards/toast";
 *
 * export const handleShowToast = onShowToast((state, action) => {
 *   console.log("Toast shown:", action.payload.message);
 *   return state;
 * });
 * ```
 */
export const onShowToast = createOnAction<ShowToastEvent>(TOAST_OP_ACTION.SHOW);

export const PI_TOAST_ACTION = registerActions(PI_TOAST_CARD, ["closed"]);

export const onToastClosed = createOnAction<PiToastClosedEvent>(
  PI_TOAST_ACTION.CLOSED,
);

/** @deprecated Use `onToastClosed` instead. */
export const onPiToastClosed = onToastClosed;

/**
 * Toast notification type/variant.
 */
export type ToastType = "default" | "success" | "error" | "info" | "warning";

/**
 * Position of the toast on the screen.
 */
export type ToastPosition =
  | "top-left"
  | "top-center"
  | "top-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right";

export type PiToastProps = {
  /**
   * Default variant for toasts shown by this card instance.
   * Can be overridden per individual toast via ShowToastEvent.variant.
   * @default 'default'
   */
  variant?: ToastType;

  /**
   * Default duration in milliseconds before the toast auto-closes.
   * Can be overridden per individual toast via ShowToastEvent.duration.
   * Set to `Infinity` to disable auto-close.
   * @default 4000
   */
  duration?: number;

  /**
   * Whether toasts from this card are dismissible by the user.
   * This is a card-level setting only; it cannot be overridden per individual toast.
   * @default true
   */
  dismissible?: boolean;

  /**
   * Custom CSS class to apply to all toasts from this card.
   */
  className?: string;
};

export type PiToastClosedEvent = {
  id?: string;
};

export type PiToastEvents = {
  onClosed: PiToastClosedEvent;
};

/**
 * Event payload for showing a toast
 */
export type ShowToastEvent = {
  cardName?: string;
  message: string;
  description?: string;
  contentCard?: PiCardRef; // Alternative: custom card for richer content
  variant?: ToastType;
  position?: ToastPosition; // Toast position on screen
  duration?: number;
};
